//! Mock backend over `mock/dataset.json` + `mock/packets.json` (generated by
//! `mock/generate.mjs`). UI agents build against this before the real backend
//! lands. `app/src/shared/mock.ts` mirrors this behaviour in the browser.
//!
//! Deliberately simple:
//! * `open_capture` accepts any path and "indexes" for ~1.5 s.
//! * The filter text understands only `host <ip>` terms (AND-ed); anything
//!   else is accepted and ignored, except unbalanced quotes/parentheses,
//!   which return `InvalidFilter` with a span.
//! * State (verdicts, pins, saved queries) is in memory only.

use std::{
    collections::{BTreeMap, HashMap, HashSet},
    sync::{Mutex, OnceLock},
    time::{Instant, SystemTime, UNIX_EPOCH},
};

use serde::Deserialize;
use serde_json::Value;

use crate::{
    Backend, CaptureRow, DnsRow, FileRow, Finding, FlowRow, FrameRow, HttpRow, Ioc, TlsRow, Ts,
    Verdict,
    error::{ApiError, ApiResult, ErrorCode, Span},
    fields::{BARE_PROTOCOLS, FIELDS, KEYWORDS, OPERATORS, SHORTHANDS},
    ipc::*,
};

const DATASET: &str = include_str!("../mock/dataset.json");
const PACKETS: &str = include_str!("../mock/packets.json");
const INGEST_MS: u128 = 1500;

#[derive(Debug, Deserialize)]
struct Dataset {
    capture: CaptureRow,
    flows: Vec<FlowRow>,
    frames: Vec<FrameRow>,
    dns: Vec<DnsRow>,
    http: Vec<HttpRow>,
    tls: Vec<TlsRow>,
    files: Vec<FileRow>,
    findings: Vec<Finding>,
    iocs: Vec<Ioc>,
}

#[derive(Default)]
struct State {
    jobs: HashMap<String, (Instant, bool)>,
    open: bool,
    verdicts: BTreeMap<String, VerdictEntry>,
    pins: Vec<Pin>,
    queries: Vec<QueryLogEntry>,
    saved: Vec<SavedQuery>,
    next_id: u64,
}

pub struct MockBackend {
    data: Dataset,
    flow_index: HashMap<u64, usize>,
    packets: OnceLock<HashMap<String, PacketView>>,
    state: Mutex<State>,
}

fn now_us() -> Ts {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_micros() as Ts)
        .unwrap_or(0)
}

impl Default for MockBackend {
    fn default() -> Self {
        Self::new()
    }
}

impl MockBackend {
    pub fn new() -> Self {
        #[allow(clippy::expect_used)]
        let data: Dataset = serde_json::from_str(DATASET).expect("mock/dataset.json is valid");
        let flow_index = data
            .flows
            .iter()
            .enumerate()
            .map(|(i, f)| (f.flow_id, i))
            .collect();
        let saved = vec![
            SavedQuery {
                name: "Long DNS names".into(),
                filter: "dns.query ~ \"*.*.*.*\" and app_proto == dns".into(),
                view: View::Dns,
            },
            SavedQuery {
                name: "Large uploads".into(),
                filter: "bytes_up > 1MB".into(),
                view: View::Flows,
            },
        ];
        Self {
            data,
            flow_index,
            packets: OnceLock::new(),
            state: Mutex::new(State {
                saved,
                ..State::default()
            }),
        }
    }

    /// Start with the capture already open (handy for UI development).
    pub fn preopened() -> Self {
        let m = Self::new();
        m.lock().open = true;
        m
    }

    fn lock(&self) -> std::sync::MutexGuard<'_, State> {
        self.state.lock().unwrap_or_else(|p| p.into_inner())
    }

    fn require_open(&self) -> ApiResult<()> {
        let mut st = self.lock();
        if st.open {
            return Ok(());
        }
        // Opening completes lazily once any job has run long enough.
        if st
            .jobs
            .values()
            .any(|(t, c)| !c && t.elapsed().as_millis() >= INGEST_MS)
        {
            st.open = true;
            return Ok(());
        }
        Err(ApiError::new(ErrorCode::NoCapture, "no capture is open"))
    }

    fn session(&self) -> CaptureSession {
        CaptureSession {
            capture: self.data.capture.clone(),
            case_id: self.data.capture.capture_id.clone(),
        }
    }

    fn check_case(&self, case_id: &str) -> ApiResult<()> {
        if case_id == self.data.capture.capture_id {
            Ok(())
        } else {
            Err(ApiError::not_found(format!("case {case_id}")))
        }
    }

    fn flow(&self, id: u64) -> Option<&FlowRow> {
        self.flow_index.get(&id).map(|&i| &self.data.flows[i])
    }

    fn packets(&self) -> &HashMap<String, PacketView> {
        self.packets.get_or_init(|| {
            #[allow(clippy::expect_used)]
            serde_json::from_str(PACKETS).expect("mock/packets.json is valid")
        })
    }

    fn with_verdicts(&self, mut f: Finding) -> Finding {
        f.verdict = self.lock().verdicts.get(&f.finding_id).map(|v| v.verdict);
        f
    }

    fn resolve(&self, ev: &EvidenceRef) -> ApiResult<crate::Evidence> {
        use crate::Evidence;
        Ok(match ev {
            EvidenceRef::Frame { frame_no } => {
                let fr = self
                    .data
                    .frames
                    .get((*frame_no as usize).wrapping_sub(1))
                    .ok_or_else(|| ApiError::not_found(format!("frame {frame_no}")))?;
                Evidence {
                    flow_ids: fr.flow_id.into_iter().collect(),
                    frame_nos: vec![*frame_no],
                    truncated: false,
                    total: 1,
                }
            }
            EvidenceRef::Flow { flow_id } => {
                let f = self
                    .flow(*flow_id)
                    .ok_or_else(|| ApiError::not_found(format!("flow {flow_id}")))?;
                Evidence {
                    flow_ids: vec![*flow_id],
                    frame_nos: vec![f.first_frame],
                    truncated: false,
                    total: 1,
                }
            }
            EvidenceRef::Finding { finding_id } => {
                let f = self
                    .data
                    .findings
                    .iter()
                    .find(|f| &f.finding_id == finding_id)
                    .ok_or_else(|| ApiError::not_found(format!("finding {finding_id}")))?;
                merge(f.reasons.iter().map(|r| &r.evidence))
            }
            EvidenceRef::Ioc { ioc_id } => self
                .data
                .iocs
                .iter()
                .find(|i| &i.ioc_id == ioc_id)
                .map(|i| i.evidence.clone())
                .ok_or_else(|| ApiError::not_found(format!("ioc {ioc_id}")))?,
            EvidenceRef::Query { .. } | EvidenceRef::Note => Evidence::default(),
        })
    }

    fn exports_dir(&self) -> ApiResult<std::path::PathBuf> {
        let d = std::env::temp_dir()
            .join("walleye-mock")
            .join(&self.data.capture.capture_id)
            .join("exports");
        std::fs::create_dir_all(&d)?;
        Ok(d)
    }
}

fn merge<'a>(evs: impl Iterator<Item = &'a crate::Evidence>) -> crate::Evidence {
    let mut flows = Vec::new();
    let mut frames = Vec::new();
    let (mut sf, mut sn) = (HashSet::new(), HashSet::new());
    let mut total = 0;
    let mut truncated = false;
    for e in evs {
        total += e.total;
        truncated |= e.truncated;
        flows.extend(e.flow_ids.iter().filter(|x| sf.insert(**x)));
        frames.extend(e.frame_nos.iter().filter(|x| sn.insert(**x)));
    }
    crate::Evidence {
        flow_ids: flows,
        frame_nos: frames,
        truncated,
        total,
    }
}

/// Validate quotes/parens and pull `host <ip>` terms out of a filter.
pub fn mock_parse_filter(filter: &str) -> ApiResult<Vec<String>> {
    let mut depth: i32 = 0;
    let mut open_at = 0usize;
    let mut in_str = false;
    let mut str_at = 0usize;
    for (i, c) in filter.char_indices() {
        match c {
            '"' => {
                in_str = !in_str;
                str_at = i;
            }
            '(' if !in_str => {
                if depth == 0 {
                    open_at = i;
                }
                depth += 1;
            }
            ')' if !in_str => {
                depth -= 1;
                if depth < 0 {
                    return Err(ApiError::invalid_filter(
                        "unexpected ')'",
                        Span {
                            start: i as u32,
                            end: i as u32 + 1,
                        },
                    ));
                }
            }
            _ => {}
        }
    }
    if in_str {
        return Err(ApiError::invalid_filter(
            "unterminated string",
            Span {
                start: str_at as u32,
                end: filter.len() as u32,
            },
        ));
    }
    if depth > 0 {
        return Err(ApiError::invalid_filter(
            "unclosed '('",
            Span {
                start: open_at as u32,
                end: open_at as u32 + 1,
            },
        ));
    }
    let toks: Vec<&str> = filter
        .split(|c: char| c.is_whitespace() || c == '(' || c == ')')
        .filter(|t| !t.is_empty())
        .collect();
    let mut hosts = Vec::new();
    for w in toks.windows(2) {
        if w[0] == "host" {
            hosts.push(w[1].to_string());
        }
    }
    Ok(hosts)
}

fn view_rows(d: &Dataset, view: View) -> Vec<Value> {
    fn j<T: serde::Serialize>(v: &[T]) -> Vec<Value> {
        v.iter()
            .map(|r| serde_json::to_value(r).unwrap_or(Value::Null))
            .collect()
    }
    match view {
        View::Flows => j(&d.flows),
        View::Dns => j(&d.dns),
        View::Http => j(&d.http),
        View::Tls => j(&d.tls),
        View::Files => j(&d.files),
        View::Frames => j(&d.frames),
    }
}

fn rowset(view: View, rows: Vec<Value>) -> ApiResult<RowSet> {
    let arr = Value::Array(rows);
    let e = |e: serde_json::Error| ApiError::internal(e.to_string());
    Ok(match view {
        View::Flows => RowSet::Flows(serde_json::from_value(arr).map_err(e)?),
        View::Dns => RowSet::Dns(serde_json::from_value(arr).map_err(e)?),
        View::Http => RowSet::Http(serde_json::from_value(arr).map_err(e)?),
        View::Tls => RowSet::Tls(serde_json::from_value(arr).map_err(e)?),
        View::Files => RowSet::Files(serde_json::from_value(arr).map_err(e)?),
        View::Frames => RowSet::Frames(serde_json::from_value(arr).map_err(e)?),
    })
}

fn cmp_values(a: &Value, b: &Value) -> std::cmp::Ordering {
    use std::cmp::Ordering::*;
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => {
            x.as_f64().partial_cmp(&y.as_f64()).unwrap_or(Equal)
        }
        (Value::String(x), Value::String(y)) => x.cmp(y),
        (Value::Bool(x), Value::Bool(y)) => x.cmp(y),
        (Value::Null, Value::Null) => Equal,
        (Value::Null, _) => Less,
        (_, Value::Null) => Greater,
        _ => a.to_string().cmp(&b.to_string()),
    }
}

fn i64_of(v: &Value, k: &str) -> i64 {
    v.get(k).and_then(Value::as_i64).unwrap_or(0)
}

pub(crate) fn frame_summary(fr: &FrameRow, flow: Option<&FlowRow>) -> String {
    let Some(f) = flow else {
        return format!("Frame {} len={}", fr.frame_no, fr.caplen);
    };
    let (sp, dp) = match fr.direction {
        Some(crate::Direction::Down) => (f.dst_port, f.src_port),
        _ => (f.src_port, f.dst_port),
    };
    match f.proto {
        6 => {
            let fl = fr.tcp_flags.unwrap_or(0);
            let names: Vec<&str> = [
                (0x02, "SYN"),
                (0x01, "FIN"),
                (0x04, "RST"),
                (0x08, "PSH"),
                (0x10, "ACK"),
                (0x20, "URG"),
            ]
            .iter()
            .filter(|(b, _)| fl & b != 0)
            .map(|(_, n)| *n)
            .collect();
            format!(
                "TCP {sp} → {dp} [{}] len={}",
                names.join(", "),
                fr.payload_len
            )
        }
        17 => format!(
            "UDP {sp} → {dp} {}len={}",
            f.app_proto
                .as_deref()
                .map(|a| format!("{} ", a.to_uppercase()))
                .unwrap_or_default(),
            fr.payload_len
        ),
        p => format!("IP proto {p} len={}", fr.payload_len),
    }
}

impl Backend for MockBackend {
    fn open_capture(&self, path: &str) -> ApiResult<JobId> {
        if path.trim().is_empty() {
            return Err(ApiError::new(ErrorCode::InvalidArgument, "empty path"));
        }
        let mut st = self.lock();
        st.next_id += 1;
        let id = format!("job-{}", st.next_id);
        st.jobs.insert(id.clone(), (Instant::now(), false));
        Ok(id)
    }

    fn ingest_status(&self, job_id: &str) -> ApiResult<IngestStatus> {
        let mut st = self.lock();
        let (start, cancelled) = *st
            .jobs
            .get(job_id)
            .ok_or_else(|| ApiError::not_found(format!("job {job_id}")))?;
        let total = self.data.capture.size_bytes;
        let ms = start.elapsed().as_millis();
        let frac = (ms as f64 / INGEST_MS as f64).min(1.0);
        let phase = if cancelled {
            IngestPhase::Cancelled
        } else if frac >= 1.0 {
            st.open = true;
            IngestPhase::Done
        } else if frac < 0.1 {
            IngestPhase::Hashing
        } else if frac < 0.85 {
            IngestPhase::Indexing
        } else {
            IngestPhase::Detecting
        };
        Ok(IngestStatus {
            job_id: job_id.to_string(),
            phase,
            pct: (frac * 100.0).round(),
            bytes_done: (total as f64 * frac) as u64,
            bytes_total: total,
            eta_s: (phase != IngestPhase::Done)
                .then(|| (INGEST_MS as f64 - ms as f64).max(0.0) / 1000.0),
            error: None,
            resumed: false,
            session: (phase == IngestPhase::Done).then(|| self.session()),
        })
    }

    fn cancel_ingest(&self, job_id: &str) -> ApiResult<()> {
        let mut st = self.lock();
        let j = st
            .jobs
            .get_mut(job_id)
            .ok_or_else(|| ApiError::not_found(format!("job {job_id}")))?;
        j.1 = true;
        Ok(())
    }

    fn current_capture(&self) -> ApiResult<Option<CaptureSession>> {
        Ok(self.require_open().ok().map(|_| self.session()))
    }

    fn query(&self, req: &QueryRequest) -> ApiResult<Page> {
        self.require_open()?;
        let t0 = Instant::now();
        if req.limit == 0 || req.limit > 10_000 {
            return Err(ApiError::new(
                ErrorCode::InvalidArgument,
                "limit must be 1..=10000",
            ));
        }
        let hosts: HashSet<String> = req.hosts.iter().cloned().collect();
        let filter_hosts = mock_parse_filter(&req.filter)?;
        let flow_ids: HashSet<u64> = req.flow_ids.iter().copied().collect();
        let host_of = |row: &Value| -> Option<(String, String)> {
            if let (Some(s), Some(d)) = (row.get("src_ip"), row.get("dst_ip")) {
                return Some((s.as_str()?.to_string(), d.as_str()?.to_string()));
            }
            let f = self.flow(row.get("flow_id")?.as_u64()?)?;
            Some((f.src_ip.clone(), f.dst_ip.clone()))
        };
        let mut rows: Vec<Value> = view_rows(&self.data, req.view)
            .into_iter()
            .filter(|r| {
                if let Some(tr) = &req.time_range {
                    let ok = if req.view == View::Flows {
                        tr.overlaps(i64_of(r, "ts_start"), i64_of(r, "ts_end"))
                    } else {
                        tr.contains(i64_of(r, "ts"))
                    };
                    if !ok {
                        return false;
                    }
                }
                if !flow_ids.is_empty() {
                    match r.get("flow_id").and_then(Value::as_u64) {
                        Some(id) if flow_ids.contains(&id) => {}
                        _ => return false,
                    }
                }
                if !hosts.is_empty() || !filter_hosts.is_empty() {
                    let Some((s, d)) = host_of(r) else {
                        return false;
                    };
                    if !hosts.is_empty() && !hosts.contains(&s) && !hosts.contains(&d) {
                        return false;
                    }
                    if !filter_hosts.iter().all(|h| *h == s || *h == d) {
                        return false;
                    }
                }
                true
            })
            .collect();
        if let Some(sort) = &req.sort {
            rows.sort_by(|a, b| {
                let o = cmp_values(
                    a.get(&sort.column).unwrap_or(&Value::Null),
                    b.get(&sort.column).unwrap_or(&Value::Null),
                );
                if sort.desc { o.reverse() } else { o }
            });
        }
        let total = rows.len();
        let offset: usize = match &req.cursor {
            Some(c) => c
                .parse()
                .map_err(|_| ApiError::new(ErrorCode::InvalidArgument, "bad cursor"))?,
            None => 0,
        };
        let end = (offset + req.limit as usize).min(total);
        let page: Vec<Value> = rows
            .get(offset.min(total)..end)
            .map(<[Value]>::to_vec)
            .unwrap_or_default();
        let n = page.len() as u64;
        let data = rowset(req.view, page)?;
        let sql = Some(format!("-- mock backend: {:?} view, no SQL", req.view));
        self.lock().queries.push(QueryLogEntry {
            filter: req.filter.clone(),
            view: req.view,
            time_range: req.time_range,
            sql: sql.clone(),
            rows: n,
            at: now_us(),
        });
        Ok(Page {
            data,
            next_cursor: (end < total).then(|| end.to_string()),
            total: Some(total as u64),
            sql,
            elapsed_ms: t0.elapsed().as_secs_f64() * 1000.0,
        })
    }

    fn timeline(&self, req: &TimelineRequest) -> ApiResult<Lanes> {
        self.require_open()?;
        let hosts_filter = mock_parse_filter(&req.filter)?;
        let cap = &self.data.capture;
        let range = req.time_range.unwrap_or(TimeRange {
            start: cap.first_ts,
            end: cap.last_ts + 1,
        });
        let span_ms = ((range.end - range.start).max(1) as u64).div_ceil(1000);
        let bucket_ms = req.bucket_ms.max(1).max(span_ms.div_ceil(2000));
        let bucket_us = bucket_ms as i64 * 1000;
        let mut per_host: HashMap<&str, BTreeMap<i64, crate::ipc::Bucket>> = HashMap::new();
        let mut totals: HashMap<&str, u64> = HashMap::new();
        for f in &self.data.flows {
            if !range.contains(f.ts_start) {
                continue;
            }
            if !hosts_filter
                .iter()
                .all(|h| *h == f.src_ip || *h == f.dst_ip)
            {
                continue;
            }
            let t = range.start + (f.ts_start - range.start) / bucket_us * bucket_us;
            let b = per_host
                .entry(&f.src_ip)
                .or_default()
                .entry(t)
                .or_insert_with(|| crate::ipc::Bucket {
                    t,
                    ..Default::default()
                });
            if f.bytes_up + f.bytes_down >= 1 << 20 {
                b.bulk += 1;
            } else {
                match f.app_proto.as_deref() {
                    Some("dns") => b.dns += 1,
                    Some("tls") => b.tls += 1,
                    Some("http") => b.http += 1,
                    _ => b.other += 1,
                }
            }
            *totals.entry(&f.src_ip).or_default() += 1;
        }
        let mut order: Vec<(&str, u64)> = totals.into_iter().collect();
        order.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(b.0)));
        let max_lanes = req.max_lanes.max(1) as usize;
        let score = |h: &str| {
            self.data
                .findings
                .iter()
                .filter(|f| f.entity == h)
                .map(|f| f.score)
                .fold(None, |a: Option<f64>, s| Some(a.map_or(s, |a| a.max(s))))
        };
        let mut lanes = Vec::new();
        let mut other: BTreeMap<i64, crate::ipc::Bucket> = BTreeMap::new();
        let mut other_total = 0;
        for (i, (h, total)) in order.iter().enumerate() {
            let buckets = per_host.remove(h).unwrap_or_default();
            if i < max_lanes {
                lanes.push(Lane {
                    host: h.to_string(),
                    is_other: false,
                    total: *total,
                    max_score: score(h),
                    buckets: buckets.into_values().collect(),
                });
            } else {
                other_total += total;
                for (t, b) in buckets {
                    let o = other.entry(t).or_insert_with(|| crate::ipc::Bucket {
                        t,
                        ..Default::default()
                    });
                    o.dns += b.dns;
                    o.tls += b.tls;
                    o.http += b.http;
                    o.bulk += b.bulk;
                    o.other += b.other;
                }
            }
        }
        if other_total > 0 {
            lanes.push(Lane {
                host: "other".into(),
                is_other: true,
                total: other_total,
                max_score: None,
                buckets: other.into_values().collect(),
            });
        }
        Ok(Lanes {
            bucket_ms,
            range,
            lanes,
        })
    }

    fn flow_frames(&self, flow_id: u64) -> ApiResult<Vec<FrameRef>> {
        self.require_open()?;
        let flow = self
            .flow(flow_id)
            .ok_or_else(|| ApiError::not_found(format!("flow {flow_id}")))?;
        let lo = (flow.first_frame as usize).saturating_sub(1);
        let hi = (flow.last_frame as usize).min(self.data.frames.len());
        Ok(self.data.frames[lo..hi]
            .iter()
            .filter(|fr| fr.flow_id == Some(flow_id))
            .map(|fr| FrameRef {
                frame_no: fr.frame_no,
                ts: fr.ts,
                caplen: fr.caplen,
                wirelen: fr.wirelen,
                direction: fr.direction,
                tcp_flags: fr.tcp_flags,
                payload_len: fr.payload_len,
                summary: frame_summary(fr, Some(flow)),
            })
            .collect())
    }

    fn packet(&self, frame_no: u64) -> ApiResult<PacketView> {
        self.require_open()?;
        self.packets()
            .get(&frame_no.to_string())
            .cloned()
            .ok_or_else(|| {
                ApiError::not_found(format!("mock dataset has no bytes for frame {frame_no}"))
            })
    }

    fn autocomplete(&self, partial: &str, cursor_pos: u32) -> ApiResult<Vec<Suggestion>> {
        let cur = (cursor_pos as usize).min(partial.len());
        let cur = (0..=cur)
            .rev()
            .find(|i| partial.is_char_boundary(*i))
            .unwrap_or(0);
        let before = &partial[..cur];
        let start = before
            .rfind(|c: char| c.is_whitespace() || c == '(')
            .map(|i| i + 1)
            .unwrap_or(0);
        let word = &before[start..];
        let prev = before[..start].split_whitespace().last().unwrap_or("");
        let mk = |label: &str, kind, detail: Option<&str>| Suggestion {
            label: label.to_string(),
            insert_text: label.to_string(),
            kind,
            detail: detail.map(str::to_string),
            replace_start: start as u32,
            replace_end: cur as u32,
        };
        let mut out = Vec::new();
        if FIELDS.iter().any(|f| f.name == prev) {
            out.extend(
                OPERATORS
                    .iter()
                    .filter(|o| o.starts_with(word))
                    .map(|o| mk(o, SuggestionKind::Operator, None)),
            );
        } else if prev == "host" || prev == "src" || prev == "dst" {
            let mut hosts: Vec<&str> = self.data.flows.iter().map(|f| f.src_ip.as_str()).collect();
            hosts.sort_unstable();
            hosts.dedup();
            out.extend(
                hosts
                    .into_iter()
                    .filter(|h| h.starts_with(word))
                    .take(20)
                    .map(|h| mk(h, SuggestionKind::Value, Some("host"))),
            );
        } else {
            out.extend(
                FIELDS
                    .iter()
                    .filter(|f| f.name.starts_with(word))
                    .map(|f| mk(f.name, SuggestionKind::Field, Some(f.doc))),
            );
            out.extend(
                SHORTHANDS
                    .iter()
                    .chain(KEYWORDS)
                    .chain(BARE_PROTOCOLS)
                    .filter(|k| !word.is_empty() && k.starts_with(word))
                    .map(|k| mk(k, SuggestionKind::Keyword, None)),
            );
            let st = self.lock();
            out.extend(
                st.saved
                    .iter()
                    .filter(|s| {
                        start == 0 && s.name.to_lowercase().starts_with(&word.to_lowercase())
                    })
                    .map(|s| Suggestion {
                        label: s.name.clone(),
                        insert_text: s.filter.clone(),
                        kind: SuggestionKind::Saved,
                        detail: Some(s.filter.clone()),
                        replace_start: 0,
                        replace_end: partial.len() as u32,
                    }),
            );
        }
        out.truncate(50);
        Ok(out)
    }

    fn list_saved_queries(&self) -> ApiResult<Vec<SavedQuery>> {
        Ok(self.lock().saved.clone())
    }

    fn save_query(&self, query: &SavedQuery) -> ApiResult<()> {
        if query.name.trim().is_empty() {
            return Err(ApiError::new(ErrorCode::InvalidArgument, "name is empty"));
        }
        mock_parse_filter(&query.filter)?;
        let mut st = self.lock();
        st.saved.retain(|s| s.name != query.name);
        st.saved.push(query.clone());
        Ok(())
    }

    fn delete_saved_query(&self, name: &str) -> ApiResult<()> {
        self.lock().saved.retain(|s| s.name != name);
        Ok(())
    }

    fn findings(&self, filter: Option<&FindingsFilter>) -> ApiResult<Vec<Finding>> {
        self.require_open()?;
        let mut out: Vec<Finding> = self
            .data
            .findings
            .iter()
            .filter(|f| {
                let Some(q) = filter else { return true };
                q.min_score.is_none_or(|m| f.score >= m)
                    && q.detector.as_ref().is_none_or(|d| &f.detector == d)
                    && q.entity.as_ref().is_none_or(|e| &f.entity == e)
                    && q.time_range
                        .is_none_or(|tr| tr.overlaps(f.ts_first, f.ts_last))
            })
            .cloned()
            .map(|f| self.with_verdicts(f))
            .collect();
        out.sort_by(|a, b| b.score.total_cmp(&a.score));
        Ok(out)
    }

    fn set_verdict(&self, finding_id: &str, verdict: Verdict, note: &str) -> ApiResult<()> {
        self.require_open()?;
        if !self
            .data
            .findings
            .iter()
            .any(|f| f.finding_id == finding_id)
        {
            return Err(ApiError::not_found(format!("finding {finding_id}")));
        }
        self.lock().verdicts.insert(
            finding_id.to_string(),
            VerdictEntry {
                finding_id: finding_id.to_string(),
                verdict,
                note: note.to_string(),
                at: now_us(),
            },
        );
        Ok(())
    }

    fn iocs(&self, case_id: &str) -> ApiResult<Vec<Ioc>> {
        self.require_open()?;
        self.check_case(case_id)?;
        Ok(self.data.iocs.clone())
    }

    fn export_iocs(&self, case_id: &str, format: IocFormat) -> ApiResult<String> {
        self.require_open()?;
        self.check_case(case_id)?;
        let dir = self.exports_dir()?;
        let (name, body) = match format {
            IocFormat::Json => (
                "iocs.json",
                serde_json::to_string_pretty(&self.data.iocs)
                    .map_err(|e| ApiError::internal(e.to_string()))?,
            ),
            IocFormat::Csv => {
                let mut s = String::from("type,defanged,first_seen,allowlisted,frame_nos\n");
                for i in &self.data.iocs {
                    let t = serde_json::to_value(i.ioc_type)
                        .ok()
                        .and_then(|v| v.as_str().map(str::to_string))
                        .unwrap_or_default();
                    let frames: Vec<String> =
                        i.evidence.frame_nos.iter().map(u64::to_string).collect();
                    s.push_str(&format!(
                        "{t},\"{}\",{},{},\"{}\"\n",
                        i.defanged.replace('"', "\"\""),
                        i.first_seen,
                        i.allowlisted,
                        frames.join(" ")
                    ));
                }
                ("iocs.csv", s)
            }
        };
        let p = dir.join(name);
        std::fs::write(&p, body)?;
        Ok(p.to_string_lossy().into_owned())
    }

    fn get_case(&self, case_id: &str) -> ApiResult<Case> {
        self.require_open()?;
        self.check_case(case_id)?;
        let st = self.lock();
        Ok(Case {
            case_id: case_id.to_string(),
            capture: self.data.capture.clone(),
            pins: st.pins.clone(),
            verdicts: st.verdicts.values().cloned().collect(),
            queries: st.queries.clone(),
        })
    }

    fn case_pin(&self, case_id: &str, evidence: &EvidenceRef, note: &str) -> ApiResult<Pin> {
        self.require_open()?;
        self.check_case(case_id)?;
        let resolved = self.resolve(evidence)?;
        let mut st = self.lock();
        st.next_id += 1;
        let pin = Pin {
            pin_id: format!("pin-{}", st.next_id),
            evidence: evidence.clone(),
            note: note.to_string(),
            resolved,
            created_at: now_us(),
        };
        st.pins.push(pin.clone());
        Ok(pin)
    }

    fn case_unpin(&self, case_id: &str, pin_id: &str) -> ApiResult<()> {
        self.check_case(case_id)?;
        let mut st = self.lock();
        let n = st.pins.len();
        st.pins.retain(|p| p.pin_id != pin_id);
        if st.pins.len() == n {
            return Err(ApiError::not_found(format!("pin {pin_id}")));
        }
        Ok(())
    }

    fn case_update_note(&self, case_id: &str, pin_id: &str, note: &str) -> ApiResult<Pin> {
        self.check_case(case_id)?;
        let mut st = self.lock();
        let pin = st
            .pins
            .iter_mut()
            .find(|p| p.pin_id == pin_id)
            .ok_or_else(|| ApiError::not_found(format!("pin {pin_id}")))?;
        pin.note = note.to_string();
        Ok(pin.clone())
    }

    fn export_report(
        &self,
        case_id: &str,
        format: ReportFormat,
        _timeline_png_base64: Option<&str>,
    ) -> ApiResult<String> {
        self.require_open()?;
        self.check_case(case_id)?;
        if format == ReportFormat::Pdf {
            return Err(ApiError::new(
                ErrorCode::InvalidArgument,
                "mock backend exports Markdown only",
            ));
        }
        let c = &self.data.capture;
        let mut md = format!(
            "# Walleye case {case_id} (MOCK)\n\nCapture: `{}`  \nSHA-256: `{}`\n\n## Findings\n\n",
            c.path, c.sha256
        );
        for f in self.findings(None)? {
            md.push_str(&format!("### {} — score {:.0}\n\n", f.title, f.score));
            for r in &f.reasons {
                let frames: Vec<String> = r
                    .evidence
                    .frame_nos
                    .iter()
                    .take(10)
                    .map(|n| format!("#{n}"))
                    .collect();
                md.push_str(&format!(
                    "- {} (frames {}; sha256 {})\n",
                    r.explanation,
                    frames.join(", "),
                    &c.sha256[..12]
                ));
            }
            md.push('\n');
        }
        let p = self.exports_dir()?.join("report.md");
        std::fs::write(&p, md)?;
        Ok(p.to_string_lossy().into_owned())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn open() -> MockBackend {
        MockBackend::preopened()
    }

    #[test]
    fn dataset_loads_and_is_consistent() {
        let m = open();
        assert!(!m.data.flows.is_empty());
        assert_eq!(m.data.capture.frame_count as usize, m.data.frames.len());
        for (i, fr) in m.data.frames.iter().enumerate() {
            assert_eq!(fr.frame_no as usize, i + 1);
        }
        for f in &m.data.findings {
            assert!(!f.reasons.is_empty());
            for r in &f.reasons {
                assert!(!r.evidence.is_empty(), "{} {}", f.finding_id, r.rule_id);
                for id in &r.evidence.flow_ids {
                    assert!(m.flow(*id).is_some());
                }
            }
        }
    }

    #[test]
    fn requires_open_capture() {
        let m = MockBackend::new();
        let req = QueryRequest {
            filter: String::new(),
            view: View::Flows,
            time_range: None,
            hosts: vec![],
            flow_ids: vec![],
            sort: None,
            limit: 10,
            cursor: None,
        };
        assert_eq!(m.query(&req).map_err(|e| e.code), Err(ErrorCode::NoCapture));
    }

    #[test]
    fn query_paginates_and_filters_hosts() {
        let m = open();
        let mut req = QueryRequest {
            filter: "host 10.0.0.23".into(),
            view: View::Flows,
            time_range: None,
            hosts: vec![],
            flow_ids: vec![],
            sort: Some(Sort {
                column: "bytes_down".into(),
                desc: true,
            }),
            limit: 5,
            cursor: None,
        };
        let p = m.query(&req).expect("query");
        assert_eq!(p.data.len(), 5);
        let RowSet::Flows(rows) = &p.data else {
            panic!("wrong view")
        };
        assert!(
            rows.iter()
                .all(|r| r.src_ip == "10.0.0.23" || r.dst_ip == "10.0.0.23")
        );
        assert!(rows.windows(2).all(|w| w[0].bytes_down >= w[1].bytes_down));
        req.cursor = p.next_cursor;
        let p2 = m.query(&req).expect("page 2");
        assert_eq!(p2.total, p.total);
    }

    #[test]
    fn filter_errors_have_spans() {
        let e = mock_parse_filter("dns.query ~ \"abc").expect_err("unterminated");
        assert_eq!(e.code, ErrorCode::InvalidFilter);
        assert_eq!(e.span.map(|s| s.start), Some(12));
    }

    #[test]
    fn timeline_has_other_lane() {
        let m = open();
        let l = m
            .timeline(&TimelineRequest {
                filter: String::new(),
                time_range: None,
                bucket_ms: 60_000,
                max_lanes: 3,
            })
            .expect("timeline");
        assert_eq!(l.lanes.len(), 4);
        assert!(l.lanes[3].is_other);
    }

    #[test]
    fn evidence_frames_have_packets() {
        let m = open();
        for f in &m.data.findings {
            for r in &f.reasons {
                for n in &r.evidence.frame_nos {
                    m.packet(*n).expect("evidence frame has bytes");
                }
            }
        }
    }

    #[test]
    fn pin_resolves_frames() {
        let m = open();
        let case = m.data.capture.capture_id.clone();
        let fid = m.data.findings[0].finding_id.clone();
        let pin = m
            .case_pin(&case, &EvidenceRef::Finding { finding_id: fid }, "c2")
            .expect("pin");
        assert!(!pin.resolved.frame_nos.is_empty());
        assert_eq!(m.get_case(&case).expect("case").pins.len(), 1);
    }

    #[test]
    fn ingest_job_completes() {
        let m = MockBackend::new();
        let j = m.open_capture("/x.pcap").expect("job");
        let s = m.ingest_status(&j).expect("status");
        assert_ne!(s.phase, IngestPhase::Done);
    }
}
